package au.com.roningroup.patrollink;
import org.junit.Test;import static org.junit.Assert.*;
public final class CaptureLinkPolicyTest {
 @Test public void ExistingAndReadOnlyRootReportRoutesAreAccepted(){for(String p:new String[]{"Issues/IssueDetails.aspx","Issues/IssueReport.aspx","ViewIssue.aspx","Reports/ReportViewer.aspx"})assertTrue(CaptureLinkPolicy.allowed("https://trlsecurity.silvertracker.net/AdminCustomer/"+p+"?IssueID=1234567"));}
 @Test public void EditorsCommandsAndRepeatedMutatingParametersAreRejected(){for(String suffix:new String[]{"EditIssue.aspx?IssueID=1234567","IssueDetails.aspx?IssueID=1234567&action=delete","IssueDetails.aspx?IssueID=1234567&action=view&action=edit","IssueDetails.aspx?IssueID=1234567&mode=save"})assertFalse(CaptureLinkPolicy.allowed("https://trlsecurity.silvertracker.net/AdminCustomer/Issues/"+suffix));}
 @Test public void OriginCredentialsAndMissingStableIdentityAreRejected(){for(String u:new String[]{"http://trlsecurity.silvertracker.net/AdminCustomer/Issues/IssueDetails.aspx?IssueID=123","https://example.org/AdminCustomer/Issues/IssueDetails.aspx?IssueID=123","https://user:secret@trlsecurity.silvertracker.net/AdminCustomer/Issues/IssueDetails.aspx?IssueID=123","https://trlsecurity.silvertracker.net/AdminCustomer/Issues/IssueDetails.aspx?IssueID=123&password=secret","https://trlsecurity.silvertracker.net/AdminCustomer/Issues/IssueDetails.aspx"})assertFalse(CaptureLinkPolicy.allowed(u));}
 @Test public void StableIdsAreNumericOrProperGuids(){assertTrue(CaptureLinkPolicy.stableId("1234567"));assertTrue(CaptureLinkPolicy.stableId("12345678-1234-abcd-1234-123456789abc"));assertFalse(CaptureLinkPolicy.stableId("--------------------------------"));assertFalse(CaptureLinkPolicy.stableId("content-hash-or-guess"));}
}
